import { Controller, Get, Post, Put, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '근태 담당자';
const SCOPES = ['COMPANY', 'DEPARTMENT', 'EMPLOYEE'];
// 가정: 등록 시 사용 여부는 '사용'으로 시작한다.
const INITIAL_USE_YN = '사용';
// 가정: 출퇴근 체크 유형의 허용값 목록이 명세에 없어 비어 있지 않은 50자 이하 문자열이면 받는다.
const CLOCK_TYPE_MAX = 50;

interface SettingInput {
  scopeType: string;
  departmentId: string | null;
  employeeId: string | null;
  clockCheckType: string;
}

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function idOf(value: unknown, label: string): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value === 'number' && Number.isInteger(value) && value > 0) {
    return String(value);
  }
  if (typeof value === 'string' && /^[0-9]+$/.test(value)) {
    return value;
  }
  throw invalid(label + '은(는) 숫자여야 합니다.');
}

function parseInput(data: Record<string, unknown>): SettingInput {
  const scopeType = data['scopeType'];
  if (typeof scopeType !== 'string' || !SCOPES.includes(scopeType)) {
    throw invalid('설정 범위를 선택해 주세요.');
  }
  const clockCheckType = data['clockCheckType'];
  if (typeof clockCheckType !== 'string' || clockCheckType.trim() === '' || clockCheckType.length > CLOCK_TYPE_MAX) {
    throw invalid('출퇴근 체크 유형을 입력해 주세요.');
  }
  let departmentId = idOf(data['departmentId'], '대상 부서');
  let employeeId = idOf(data['employeeId'], '대상 사원');
  if (scopeType === 'DEPARTMENT' && departmentId === null) {
    throw new ApiError(422, 'CLOCK_TARGET_REQUIRED', '부서 범위는 대상 부서를 지정해야 합니다.');
  }
  if (scopeType === 'EMPLOYEE' && employeeId === null) {
    throw new ApiError(422, 'CLOCK_TARGET_REQUIRED', '사원 범위는 대상 사원을 지정해야 합니다.');
  }
  // 범위와 관계없는 대상은 저장하지 않는다.
  if (scopeType !== 'DEPARTMENT') {
    departmentId = null;
  }
  if (scopeType !== 'EMPLOYEE') {
    employeeId = null;
  }
  return { scopeType, departmentId, employeeId, clockCheckType: clockCheckType.trim() };
}

interface Db {
  query: (sql: string, params?: Record<string, unknown>) => Promise<any[]>;
  execute: (sql: string, params?: Record<string, unknown>) => Promise<number>;
}

async function checkTargets(db: Db, input: SettingInput): Promise<void> {
  if (input.departmentId !== null) {
    const rows = await db.query(
      'SELECT department_id FROM department WHERE department_id = CAST(:id AS bigint)',
      { id: input.departmentId },
    );
    if (rows.length === 0) {
      throw new ApiError(404, 'CLOCK_TARGET_NOT_FOUND', '지정한 부서를 찾을 수 없습니다.');
    }
  }
  if (input.employeeId !== null) {
    const rows = await db.query(
      'SELECT employee_id FROM employee WHERE employee_id = CAST(:id AS bigint)',
      { id: input.employeeId },
    );
    if (rows.length === 0) {
      throw new ApiError(404, 'CLOCK_TARGET_NOT_FOUND', '지정한 사원을 찾을 수 없습니다.');
    }
  }
}

@Controller('api/v1')
export class FnSfr01704Controller {
  @Get('/clock-type-settings')
  async listClockTypeSettings(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const scopeRaw = query['scopeType'];
    let scopeType: string | null = null;
    if (scopeRaw !== undefined && scopeRaw !== null && scopeRaw !== '') {
      if (typeof scopeRaw !== 'string' || !SCOPES.includes(scopeRaw)) {
        throw invalid('설정 범위가 올바르지 않습니다.');
      }
      scopeType = scopeRaw;
    }
    const pageRaw = query['page'] === undefined || query['page'] === '' ? 0 : Number(query['page']);
    const sizeRaw = query['size'] === undefined || query['size'] === '' ? 20 : Number(query['size']);
    if (!Number.isInteger(pageRaw) || pageRaw < 0) {
      throw invalid('page는 0 이상의 정수여야 합니다.');
    }
    if (!Number.isInteger(sizeRaw) || sizeRaw < 1) {
      throw invalid('size는 1 이상의 정수여야 합니다.');
    }
    const page = pageRaw;
    const size = Math.min(sizeRaw, 200);
    return transaction(async (db) => {
      const items = await db.query(
        'SELECT clock_type_setting_id AS "clockTypeSettingId", scope_type AS "scopeType", '
          + 'department_id AS "departmentId", employee_id AS "employeeId", '
          + 'clock_check_type AS "clockCheckType", use_yn AS "useYn" '
          + 'FROM clock_type_setting '
          + 'WHERE (CAST(:scopeType AS text) IS NULL OR scope_type = CAST(:scopeType AS text)) '
          + 'ORDER BY clock_type_setting_id DESC '
          + 'LIMIT CAST(:size AS int) OFFSET CAST(:offset AS int)',
        { scopeType, size, offset: page * size },
      );
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM clock_type_setting '
          + 'WHERE (CAST(:scopeType AS text) IS NULL OR scope_type = CAST(:scopeType AS text))',
        { scopeType },
      );
      return { items, page, size, total: Number(counts[0].total) };
    });
  }

  @Post('/clock-type-settings')
  @HttpCode(200)
  async createClockTypeSetting(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const input = parseInput(data);
    return transaction(async (db) => {
      await checkTargets(db, input);
      const rows = await db.query(
        'INSERT INTO clock_type_setting (scope_type, department_id, employee_id, clock_check_type, use_yn, created_at, updated_at) '
          + 'VALUES (:scopeType, CAST(:departmentId AS bigint), CAST(:employeeId AS bigint), :clockCheckType, :useYn, now(), now()) '
          + 'RETURNING clock_type_setting_id AS "clockTypeSettingId"',
        {
          scopeType: input.scopeType,
          departmentId: input.departmentId,
          employeeId: input.employeeId,
          clockCheckType: input.clockCheckType,
          useYn: INITIAL_USE_YN,
        },
      );
      return { clockTypeSettingId: Number(rows[0].clockTypeSettingId) };
    });
  }

  @Put('/clock-type-settings/:clockTypeSettingId')
  async updateClockTypeSetting(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const settingId = req.params['clockTypeSettingId'];
    if (typeof settingId !== 'string' || !/^[0-9]+$/.test(settingId)) {
      throw invalid('출퇴근 체크 유형 설정 ID가 올바르지 않습니다.');
    }
    const data = checks.inputOf(req.body);
    const input = parseInput(data);
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT clock_type_setting_id FROM clock_type_setting WHERE clock_type_setting_id = CAST(:id AS bigint)',
        { id: settingId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'CLOCK_TYPE_SETTING_NOT_FOUND', '출퇴근 체크 유형 설정을 찾을 수 없습니다.');
      }
      await checkTargets(db, input);
      await db.execute(
        'UPDATE clock_type_setting SET scope_type = :scopeType, department_id = CAST(:departmentId AS bigint), '
          + 'employee_id = CAST(:employeeId AS bigint), clock_check_type = :clockCheckType, updated_at = now() '
          + 'WHERE clock_type_setting_id = CAST(:id AS bigint)',
        {
          id: settingId,
          scopeType: input.scopeType,
          departmentId: input.departmentId,
          employeeId: input.employeeId,
          clockCheckType: input.clockCheckType,
        },
      );
      return { clockTypeSettingId: Number(settingId) };
    });
  }
}

