import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Form,
  Field,
  TextInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const PAGE_SIZE = 20;
const SCOPE_OPTIONS: [string, string][] = [
  ['COMPANY', '법인 공통'],
  ['DEPARTMENT', '부서'],
  ['EMPLOYEE', '사원'],
];
const SCOPE_LABEL: Record<string, string> = {
  COMPANY: '법인 공통',
  DEPARTMENT: '부서',
  EMPLOYEE: '사원',
};

interface EditFormProps {
  role: string;
  target: Row | null;
  onDone: () => void;
  notify: (text: string) => void;
}

function EditForm({ role, target, onDone, notify }: EditFormProps) {
  const [scopeType, setScopeType] = useState<string>(target ? String(target['scopeType'] ?? '') : '');
  const [departmentId, setDepartmentId] = useState<number | string>(
    target && target['departmentId'] != null ? (target['departmentId'] as number) : '',
  );
  const [employeeId, setEmployeeId] = useState<number | string>(
    target && target['employeeId'] != null ? (target['employeeId'] as number) : '',
  );
  const [clockCheckType, setClockCheckType] = useState<string>(
    target ? String(target['clockCheckType'] ?? '') : '',
  );

  const submit = async () => {
    if (!scopeType) {
      throw new Error('설정 범위를 선택해 주세요.');
    }
    if (!clockCheckType.trim()) {
      throw new Error('출퇴근 체크 유형을 입력해 주세요.');
    }
    if (scopeType === 'DEPARTMENT' && departmentId === '') {
      throw new Error('부서 범위는 대상 부서를 지정해야 합니다.');
    }
    if (scopeType === 'EMPLOYEE' && employeeId === '') {
      throw new Error('사원 범위는 대상 사원을 지정해야 합니다.');
    }
    const body: Row = {
      scopeType,
      departmentId: scopeType === 'DEPARTMENT' ? departmentId : null,
      employeeId: scopeType === 'EMPLOYEE' ? employeeId : null,
      clockCheckType: clockCheckType.trim(),
    };
    if (target) {
      await call('PUT', '/clock-type-settings/' + String(target['clockTypeSettingId']), role, body);
      notify('출퇴근 체크 유형 설정을 수정했습니다.');
    } else {
      await call('POST', '/clock-type-settings', role, body);
      notify('출퇴근 체크 유형 설정을 등록했습니다.');
    }
    onDone();
  };

  return (
    <Form onSubmit={submit} submit={target ? '수정' : '등록'}>
      <Field label="설정 범위" required>
        <Select value={scopeType} onChange={setScopeType} options={SCOPE_OPTIONS} />
      </Field>
      {scopeType === 'DEPARTMENT' && (
        <Field label="대상 부서" required>
          <LookupSelect table="department" role={role} value={departmentId} onChange={setDepartmentId} />
        </Field>
      )}
      {scopeType === 'EMPLOYEE' && (
        <Field label="대상 사원" required>
          <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} />
        </Field>
      )}
      <Field label="출퇴근 체크 유형" required>
        <TextInput value={clockCheckType} onChange={setClockCheckType} />
      </Field>
    </Form>
  );
}

export default function FnSfr01704Page({ role, notify }: PageProps) {
  const [scopeInput, setScopeInput] = useState('');
  const [scopeApplied, setScopeApplied] = useState('');
  const [pageNo, setPageNo] = useState(0);
  const [drawer, setDrawer] = useState<{ target: Row | null } | null>(null);

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/clock-type-settings', role, undefined, {
      scopeType: scopeApplied,
      page: pageNo,
      size: PAGE_SIZE,
    }),
    [scopeApplied, pageNo, role],
  );

  const search = () => {
    setPageNo(0);
    setScopeApplied(scopeInput);
  };

  const reset = () => {
    setScopeInput('');
    setScopeApplied('');
    setPageNo(0);
  };

  const done = () => {
    setDrawer(null);
    reload();
  };

  const columns = [
    {
      key: 'scopeType',
      label: '설정 범위',
      render: (row: Row) => SCOPE_LABEL[String(row['scopeType'])] ?? String(row['scopeType']),
    },
    {
      key: 'target',
      label: '대상',
      render: (row: Row) => {
        if (row['departmentId'] != null) {
          return <RefName table="department" role={role} value={row['departmentId']} />;
        }
        if (row['employeeId'] != null) {
          return <RefName table="employee" role={role} value={row['employeeId']} />;
        }
        return '전체';
      },
    },
    { key: 'clockCheckType', label: '출퇴근 체크 유형' },
    { key: 'useYn', label: '사용 여부', render: (row: Row) => <Badge value={row['useYn']} /> },
    {
      key: 'actions',
      label: '처리',
      render: (row: Row) => (
        <button type="button" onClick={() => setDrawer({ target: row })}>
          수정
        </button>
      ),
    },
  ];

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>전체 설정</h2>
        <p className="big">
          <Num value={data ? data.total : 0} />
        </p>
      </section>
      <section className="box span-8">
        <h2>설정 목록</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="설정 범위">
            <Select value={scopeInput} onChange={setScopeInput} options={SCOPE_OPTIONS} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0}>
          <button type="button" onClick={() => setDrawer({ target: null })}>
            설정 등록
          </button>
        </Band>
        {error && <ErrorText text={error} />}
        <DataTable columns={columns} rows={data ? data.items : []} empty="등록된 설정이 없습니다." />
        <Pager page={pageNo} size={PAGE_SIZE} total={data ? data.total : 0} onPage={setPageNo} />
      </section>
      {drawer && (
        <Drawer
          title={drawer.target ? '출퇴근 체크 유형 설정 수정' : '출퇴근 체크 유형 설정 등록'}
          onClose={() => setDrawer(null)}
        >
          <EditForm role={role} target={drawer.target} onDone={done} notify={notify} />
        </Drawer>
      )}
    </div>
  );
}
